<!--vbase-->
<template>
  <f-btn
    v-if="show_btn"
    class="p-4"
    appearance="flat"
    @click="confirmation = true"
  >
    <Icon icon="mdi:text-recognition" width="20" height="20" />
    <q-tooltip>{{ $t('force_ocr') }}</q-tooltip>
  </f-btn>

  <q-dialog v-model="confirmation" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('restartClassification') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          data-cy="cancel"
          :label="$t('cancel')"
          appearance="cancel"
          v-close-popup
          @click="reset()"
        />
        <f-btn
          data-cy="done"
          :label="$t('proceed')"
          v-close-popup
          @click="triggerProcess()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

import helperMixin from 'src/mixins/helperMixin.js';
import {
  useDocLockStore,
  useDocumentStore,
  useDocClassificationStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';
import doc_type_sub_type_Util from 'src/utils/doc_type/doc_type_sub_type';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { documentDetailApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, doc_type_sub_type_Util],
  props: {
    show_btn: {
      type: Boolean,
      default: false,
    },
    force_ocr: {
      type: Boolean,
      default: false,
    },
  },
  
  data() {
    return {};
  },
  setup() {
    const doc_store = useDocumentStore();
    const { setDocTypeAndLanguageOrigin } = doc_store;
    const { record, language_origin, selected_doc_type } =
      storeToRefs(doc_store);

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const classification_store = useDocClassificationStore();
    const { resetStore } = classification_store;
    const {
      confirmation,
      trigger_classification,
      reset_classification,
      selected_page,
      selected_custom_model_label,
    } = storeToRefs(classification_store);

    return {
      selected_custom_model_label,
      resetStore,
      selected_page,
      setDocTypeAndLanguageOrigin,
      language_origin,
      selected_doc_type,
      sub_doc_type: ref(''),
      record,
      releaseDocLock,
      docId: ref(''),
      table_train: ref(false),
      confirmation,
      trigger_classification,
      reset_classification,
    };
  },
  watch: {
    trigger_classification: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.triggerProcess();
        }
      },
    },
  },
  mounted: function () {
    document.addEventListener(
      'trigger_classification',
      this.TriggerConfirmation,
    );
    this.isDocForTraining();
  },
  unmounted: function () {
    document.removeEventListener(
      'trigger_classification',
      this.TriggerConfirmation,
    );
  },
  methods: {
    reset() {
      this.setDocTypeAndLanguageOrigin();
      this.resetStore();
    },
    TriggerConfirmation() {
      this.triggerProcess();
    },
    async triggerProcess() {
      try {
        if (!this.selected_doc_type || this.selected_doc_type === '') {
          notify.error('Document Type is missing');
          return;
        }
        if (!this.language_origin || this.language_origin === '') {
          notify.error('Document Origin is missing');
          return;
        }

        this.setDocTypeSubDocType();
        await this.restartDoc();
        this.resetStore();
        notify.success(this.$t('NEW_CLASSIFICATION'));

        this.table_train === true
          ? this.routeForTableTrain()
          : this.routeToDashboard();
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
        this.hideLoading();
      } finally {
      }
    },

    routeToDashboard() {
      this.releaseDocLock({ doc_id: this.record.doc_id });
      this.$router.push('/dashboard');
    },

    setDocTypeSubDocType() {
      this.sub_doc_type = '';
      const doc_type_obj = this.getDocTypeSubDocType(this.selected_doc_type);
      if (
        !doc_type_obj ||
        !doc_type_obj.hasOwnProperty('doc_type_key') ||
        !doc_type_obj.hasOwnProperty('sub_doc_type')
      ) {
        return;
      }
      this.sub_doc_type = doc_type_obj.sub_doc_type;
      this.selected_doc_type = doc_type_obj.doc_type_key;
    },

    async restartDoc() {
      try {
        this.showLoading();
        let data = {} as dynamicObj;
        data.doc_type = this.selected_doc_type;
        data.doc_origin = this.language_origin;

        if (this.sub_doc_type !== '') {
          data.sub_doc_type = this.sub_doc_type;
        }

        if (this.force_ocr === true) {
          data.force_ocr = true.toString();
        }

        if (this.selected_page) {
          data.doc_start_page = this.selected_page;
        }

        if (this.selected_custom_model_label) {
          data.doc_classification_label = this.selected_custom_model_label;
        }

        await documentDetailApiService.restartClassification(data, this.docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    routeForTableTrain() {
      const openerWindow = window.opener;
      if (!openerWindow) {
        return;
      }
      openerWindow.postMessage('reload_page_with_force_ocr', '*');
      window.close();
    },

    isDocForTraining() {
      if (
        this.$route.params.table_train &&
        this.$route.params.table_train === 'true'
      ) {
        this.table_train = true;
        this.docId = String(this.$route.query.id);
      } else {
        this.docId = String(this.$route.params.id);
      }
    },
  },
});
</script>

<style lang="scss" scoped></style>
