<!--vbase-->
<template>
  <q-btn
    id="btn_add_rules"
    flat
    class="pr-6 pl-6"
    v-if="is_script_editor_available || selected_doc_type != ''"
    @click="goToScriptView"
  >
    <Icon icon="mdi:script-text-outline" width="24" height="24" />
    <q-tooltip>{{ $t('add_special_rules') }}</q-tooltip>
  </q-btn>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

import {
  useDocScriptStore,
  useDocumentStore,
  useDropdownStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
    
  props: {},
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
    doc_type_loading: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
  },
  data() {
    return {};
  },
  mounted: function () {
    this.init();
  },
  methods: {
    init() {
      if (!this.doc_loaded) {
        return;
      }

      const doc_type = this.record.doc_type;
      let filterRecord = this.doc_types_sub_types_list.filter((v: any) => {
        return v.value == doc_type;
      });

      filterRecord = filterRecord[0] || null;
      if (
        !filterRecord ||
        !filterRecord.hasOwnProperty('name') ||
        !filterRecord.name
      ) {
        return;
      }

      // get the doc_name from list
      this.selected_doc_type = filterRecord.name;
    },

    goToScriptView() {
      if (!this.doc_loaded) {
        return;
      }
      const sub_doc_type = this.record.sub_doc_type || '';
      const doctype = this.record.doc_type || '';

      if (!doctype) {
        logInfo('missing doc_type for url');
        return;
      }

      let query_params = doctype;
      if (sub_doc_type) {
        query_params = query_params + '/' + sub_doc_type;
      }

      const url = '/settings/manage-scripts/' + query_params;
      (<any>window).open(url, '_blank').focus();
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const dropdown_store = useDropdownStore();
    const { doc_types_sub_types_list, doc_type_loading } =
      storeToRefs(dropdown_store);

    const doc_script = useDocScriptStore();
    const { selected_doc_type, is_script_editor_available } =
      storeToRefs(doc_script);

    return {
      doc_type_loading,
      doc_types_sub_types_list,
      record,
      doc_loaded,
      selected_doc_type,
      is_script_editor_available,
    };
  },
});
</script>

