import { useDropdownStore } from 'src/store/main';
export default {
  methods: {
    getDocTypeSubDocType(selected_doc_type: string) {
      const dropdown_store = useDropdownStore();
      const { doc_types_sub_types_list } = dropdown_store;
      const doc_type_obj = doc_types_sub_types_list.filter(
        (doc_type: any) => doc_type.value === selected_doc_type,
      );
      if (
        !doc_type_obj ||
        !Array.isArray(doc_type_obj) ||
        doc_type_obj.length == 0 ||
        !doc_type_obj[0].hasOwnProperty('doc_type_key') ||
        doc_type_obj[0].doc_type_key == ''
      ) {
        return;
      }

      return {
        doc_type_key: doc_type_obj[0].doc_type_key,
        sub_doc_type: selected_doc_type,
      };
    },
  },
};
